// THE OBLIGATION CALENDAR — what is due, on what day, between now and the horizon.
//
// A monthly total is the wrong shape for the question people actually have. Rent on the 1st, a card
// minimum on the 3rd and an insurance renewal on the 5th is a very different week from the same
// money spread across thirty days, and a month-level figure cannot see the difference. The failure
// this prevents is arriving at a heavy week with a balance that was, on a monthly view, fine.
//
// STEPPING IS THE WHOLE PROBLEM, and it is not obvious. A monthly charge is NOT every 30 days. Step
// a 15 January bill by 30 days twelve times and it lands on 11 December — five days and, at the
// boundaries, a whole month wrong. Billing anniversaries are CALENDAR facts, so monthly, quarterly
// and annual step by calendar months and keep their day, while weekly and biweekly step by days
// because that is what they actually are.
//
// And the anchor never moves. A bill on the 31st stepped into February CLAMPS to the 28th for that
// month, then returns to the 31st in March — it does not walk backwards a few days a year, and it
// certainly does not roll over into the following month, which is what naive date arithmetic does.
import { type Money, money, sum } from "@/features/finance/lib/money";
import type { Cadence, Recurring } from "@/features/finance/lib/recurring";
import type { Position } from "@/features/finance/lib/position";

export type ObligationKind = "recurring" | "minimum";

/** How much the DATE is to be trusted. The amount is a separate question. */
export type Confidence = "observed" | "assumed";

export interface Obligation {
  /** `YYYY-MM-DD` it is expected to hit. */
  readonly date: string;
  readonly label: string;
  readonly account: string;
  /** POSITIVE amount due — a calendar of outgoings does not need signs to say which way they go. */
  readonly amount: Money;
  readonly kind: ObligationKind;
  readonly confidence: Confidence;
  /** For a recurring charge, how metronomic the observed occurrences were. */
  readonly regularity?: number;
}

export interface MonthTotal {
  readonly month: string;
  readonly total: Money;
  readonly count: number;
}

export interface ObligationCalendar {
  readonly from: string;
  readonly to: string;
  readonly obligations: readonly Obligation[];
  readonly byMonth: readonly MonthTotal[];
  /** The month that costs the most. The one to have money in place for. */
  readonly heaviest?: MonthTotal;
  /** Everything the calendar decided rather than observed. */
  readonly notes: readonly string[];
}

export interface CalendarOptions {
  readonly from: string;
  readonly to: string;
  /** Day of the month a debt's minimum is actually due, where it is known. */
  readonly minimumDueDay?: Readonly<Record<string, number>>;
  /** Include charges that look cancelled. Off by default; they are reported as a note either way. */
  readonly includeLapsed?: boolean;
}

const pad = (n: number, w = 2): string => String(n).padStart(w, "0");

/** Days in the month containing `y`/`m` (1-based month). */
const daysInMonth = (y: number, m: number): number => new Date(Date.UTC(y, m, 0)).getUTCDate();

export const addDays = (iso: string, n: number): string =>
  new Date(Date.parse(`${iso}T00:00:00Z`) + n * 86_400_000).toISOString().slice(0, 10);

/**
 * Step by CALENDAR months, keeping the day of the month and clamping where it does not exist.
 *
 * `2026-01-31` plus one month is `2026-02-28`, not `2026-03-03`. Plus TWO months is `2026-03-31`,
 * not `2026-03-28` — the anchor is the original date, so a bill on the 31st does not walk backwards
 * through the year every time it passes a short month.
 */
export function addCalendarMonths(iso: string, n: number): string {
  const y = Number(iso.slice(0, 4));
  const m = Number(iso.slice(5, 7));
  const d = Number(iso.slice(8, 10));
  const total = y * 12 + (m - 1) + n;
  const mm = ((total % 12) + 12) % 12;
  const yy = (total - mm) / 12;
  return `${pad(yy, 4)}-${pad(mm + 1)}-${pad(Math.min(d, daysInMonth(yy, mm + 1)))}`;
}

/** The nth occurrence after an anchor, by the cadence's own unit. */
function step(anchor: string, cadence: Cadence, n: number): string | undefined {
  switch (cadence) {
    case "weekly":
      return addDays(anchor, 7 * n);
    case "biweekly":
      return addDays(anchor, 14 * n);
    case "monthly":
      return addCalendarMonths(anchor, n);
    case "quarterly":
      return addCalendarMonths(anchor, 3 * n);
    case "annual":
      return addCalendarMonths(anchor, 12 * n);
    default:
      // An irregular charge has no next date to predict. Inventing one would put a number on the
      // calendar that nothing observed, which is worse than the charge being absent from it.
      return undefined;
  }
}

/** A hard cap, so a bad cadence can never spin. 5 years of weekly is comfortably inside it. */
const MAX_OCCURRENCES = 400;

function occurrences(r: Recurring, from: string, to: string): string[] {
  const out: string[] = [];
  for (let n = 1; n <= MAX_OCCURRENCES; n++) {
    const at = step(r.lastSeen, r.cadence, n);
    if (!at || at > to) break;
    if (at >= from) out.push(at);
  }
  return out;
}

export function buildCalendar(
  recurring: readonly Recurring[],
  position: Position | undefined,
  opts: CalendarOptions,
): ObligationCalendar {
  const { from, to, minimumDueDay = {}, includeLapsed = false } = opts;
  const notes: string[] = [];
  const obligations: Obligation[] = [];

  const lapsed = recurring.filter((r) => r.lapsed);
  if (lapsed.length && !includeLapsed) {
    notes.push(
      `${lapsed.length} charge(s) look cancelled and are NOT on the calendar — ${lapsed.map((r) => r.label).join(", ")}. If one of them renews, the months below are light by that much.`,
    );
  }
  const irregular = recurring.filter((r) => r.cadence === "irregular");
  if (irregular.length) {
    notes.push(
      `${irregular.length} charge(s) recur on no predictable schedule and have no date here — they will still cost money.`,
    );
  }

  for (const r of recurring) {
    if (r.lapsed && !includeLapsed) continue;
    for (const date of occurrences(r, from, to)) {
      obligations.push({
        date,
        label: r.label,
        account: r.account,
        amount: r.typical,
        kind: "recurring",
        // The DATE is observed — it came from a real rhythm. Whether the amount repeats is what
        // `regularity` and the charge's own amount stability are for.
        confidence: r.regularity >= 0.8 ? "observed" : "assumed",
        regularity: r.regularity,
      });
    }
  }

  for (const a of position?.accounts ?? []) {
    if (!a.minimumPayment || !a.owed) continue;
    const day = minimumDueDay[a.account];
    if (day === undefined) {
      notes.push(
        `the due day for ${a.institution}'s minimum is unknown — it is placed on the 1st, the earliest it could plausibly fall, so this calendar cannot be optimistic about it`,
      );
    }
    for (const month of monthsBetween(from, to)) {
      const [y, m] = [Number(month.slice(0, 4)), Number(month.slice(5, 7))];
      const at = `${month}-${pad(Math.min(day ?? 1, daysInMonth(y, m)))}`;
      if (at < from || at > to) continue;
      obligations.push({
        date: at,
        label: `${a.institution} minimum`,
        account: a.account,
        amount: a.minimumPayment,
        kind: "minimum",
        confidence: day === undefined ? "assumed" : "observed",
      });
    }
  }

  obligations.sort((x, y) => x.date.localeCompare(y.date) || x.label.localeCompare(y.label));

  const currency = obligations[0]?.amount.currency ?? position?.currency ?? "USD";
  const buckets = new Map<string, Obligation[]>();
  for (const o of obligations) {
    const key = o.date.slice(0, 7);
    const b = buckets.get(key);
    if (b) b.push(o);
    else buckets.set(key, [o]);
  }
  const byMonth: MonthTotal[] = [...buckets.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([month, os]) => ({ month, total: sum(os.map((o) => o.amount), currency), count: os.length }));

  return {
    from,
    to,
    obligations,
    byMonth,
    heaviest: byMonth.length
      ? byMonth.reduce((best, m) => (m.total.minor > best.total.minor ? m : best))
      : undefined,
    notes,
  };
}

/** Every `YYYY-MM` touched by the window, inclusive at both ends. */
export function monthsBetween(from: string, to: string): string[] {
  const out: string[] = [];
  let cur = from.slice(0, 7);
  const last = to.slice(0, 7);
  while (cur <= last && out.length < 600) {
    out.push(cur);
    cur = addCalendarMonths(`${cur}-01`, 1).slice(0, 7);
  }
  return out;
}

/** What is due inside a window — the "can I get to Friday?" question. */
export const dueBetween = (c: ObligationCalendar, from: string, to: string): readonly Obligation[] =>
  c.obligations.filter((o) => o.date >= from && o.date <= to);

/** The total for one month, zero if nothing is due — a month with no obligations is a real answer. */
export function monthTotal(c: ObligationCalendar, month: string, currency: string): Money {
  return c.byMonth.find((m) => m.month === month)?.total ?? money(0, currency);
}

/** The heaviest run of `days` consecutive days in the window. Where a month-level view goes blind. */
export function heaviestWindow(c: ObligationCalendar, days: number): { from: string; to: string; total: Money } | undefined {
  if (!c.obligations.length) return undefined;
  const currency = c.obligations[0].amount.currency;
  let best: { from: string; to: string; total: Money } | undefined;
  for (const o of c.obligations) {
    const end = addDays(o.date, days - 1);
    const total = sum(dueBetween(c, o.date, end).map((x) => x.amount), currency);
    if (!best || total.minor > best.total.minor) best = { from: o.date, to: end, total };
  }
  return best;
}

/** Debts whose minimum is on the calendar — what keeps every account current. */
export const minimumsOn = (c: ObligationCalendar): readonly Obligation[] =>
  c.obligations.filter((o) => o.kind === "minimum");

