import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import type { Cadence, Recurring } from "@/features/finance/lib/recurring";
import type { Position } from "@/features/finance/lib/position";
import {
  addCalendarMonths,
  addDays,
  buildCalendar,
  dueBetween,
  heaviestWindow,
  minimumsOn,
  monthTotal,
  monthsBetween,
} from "@/features/finance/lib/obligations";

// SYNTHETIC FIXTURES ONLY. No real statement, balance or account number belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");

const charge = (over: Partial<Recurring> = {}): Recurring => ({
  key: "example sub",
  label: "EXAMPLE SUBSCRIPTION",
  account: "card",
  cadence: "monthly" as Cadence,
  typical: usd(14.99),
  annualised: usd(179.88),
  occurrences: 6,
  firstSeen: "2026-01-15",
  lastSeen: "2026-06-15",
  regularity: 1,
  amountStability: 1,
  lapsed: false,
  ...over,
});

const positionWith = (accounts: Position["accounts"]): Position => ({
  asOf: "2026-06-30",
  currency: "USD",
  accounts,
  netWorth: usd(0),
  liquid: usd(0),
  totalDebt: usd(0),
  dailyInterest: usd(0),
  minimumsDue: usd(0),
  complete: true,
  problems: [],
  provenance: "synthetic",
});

describe("addCalendarMonths — a monthly bill is a CALENDAR fact", () => {
  it("keeps the day of the month", () => {
    expect(addCalendarMonths("2026-01-15", 1)).toBe("2026-02-15");
    expect(addCalendarMonths("2026-01-15", 11)).toBe("2026-12-15");
    // 30-day stepping drifts five days a year, and at a month boundary it is not a drift but a
    // wrong month: a bill on 31 January stepped 30 days lands on 2 March, so February shows nothing
    // due and March shows it twice. That is the whole reason this function exists.
    expect(addCalendarMonths("2026-01-15", 12)).toBe("2027-01-15");
    expect(addDays("2026-01-15", 30 * 12)).toBe("2027-01-10");
    expect(addDays("2026-01-31", 30)).toBe("2026-03-02");
    expect(addCalendarMonths("2026-01-31", 1)).toBe("2026-02-28");
  });

  it("CLAMPS into a short month instead of rolling into the next one", () => {
    // Naive date arithmetic turns 31 February into 3 March, which puts a bill in a month it is not
    // due in and, worse, makes the February total look empty.
    expect(addCalendarMonths("2026-01-31", 1)).toBe("2026-02-28");
    expect(addCalendarMonths("2024-01-31", 1)).toBe("2024-02-29");
    expect(addCalendarMonths("2026-08-31", 1)).toBe("2026-09-30");
  });

  it("anchors on the ORIGINAL day, so a 31st bill does not walk backwards through the year", () => {
    expect(addCalendarMonths("2026-01-31", 2)).toBe("2026-03-31");
    expect(addCalendarMonths("2026-01-31", 4)).toBe("2026-05-31");
  });

  it("crosses year boundaries in both directions", () => {
    expect(addCalendarMonths("2026-11-20", 3)).toBe("2027-02-20");
    expect(addCalendarMonths("2026-02-20", -3)).toBe("2025-11-20");
  });
});

describe("monthsBetween", () => {
  it("is inclusive at both ends", () => {
    expect(monthsBetween("2026-06-15", "2026-09-02")).toEqual(["2026-06", "2026-07", "2026-08", "2026-09"]);
    expect(monthsBetween("2026-06-15", "2026-06-30")).toEqual(["2026-06"]);
  });

  it("crosses a year end", () => {
    expect(monthsBetween("2026-11-10", "2027-01-05")).toEqual(["2026-11", "2026-12", "2027-01"]);
  });
});

describe("buildCalendar — projecting a charge forward", () => {
  it("puts a monthly charge on the same day of each month", () => {
    const c = buildCalendar([charge()], undefined, { from: "2026-07-01", to: "2026-12-31" });
    expect(c.obligations.map((o) => o.date)).toEqual([
      "2026-07-15", "2026-08-15", "2026-09-15", "2026-10-15", "2026-11-15", "2026-12-15",
    ]);
    expect(c.obligations.every((o) => o.amount.minor === usd(14.99).minor)).toBe(true);
  });

  it("steps weekly and biweekly by DAYS, because that is what they are", () => {
    const weekly = buildCalendar(
      [charge({ cadence: "weekly", lastSeen: "2026-06-29" })],
      undefined,
      { from: "2026-07-01", to: "2026-07-31" },
    );
    expect(weekly.obligations.map((o) => o.date)).toEqual(["2026-07-06", "2026-07-13", "2026-07-20", "2026-07-27"]);

    const fortnight = buildCalendar(
      [charge({ cadence: "biweekly", lastSeen: "2026-06-29" })],
      undefined,
      { from: "2026-07-01", to: "2026-07-31" },
    );
    expect(fortnight.obligations.map((o) => o.date)).toEqual(["2026-07-13", "2026-07-27"]);
  });

  it("steps quarterly and annual by calendar months too", () => {
    const q = buildCalendar([charge({ cadence: "quarterly", lastSeen: "2026-03-31" })], undefined, {
      from: "2026-04-01",
      to: "2027-03-31",
    });
    expect(q.obligations.map((o) => o.date)).toEqual(["2026-06-30", "2026-09-30", "2026-12-31", "2027-03-31"]);

    const a = buildCalendar([charge({ cadence: "annual", lastSeen: "2026-02-14" })], undefined, {
      from: "2026-03-01",
      to: "2028-12-31",
    });
    expect(a.obligations.map((o) => o.date)).toEqual(["2027-02-14", "2028-02-14"]);
  });

  it("never emits the occurrence it started from", () => {
    const c = buildCalendar([charge({ lastSeen: "2026-07-15" })], undefined, { from: "2026-07-01", to: "2026-09-30" });
    expect(c.obligations.map((o) => o.date)).toEqual(["2026-08-15", "2026-09-15"]);
  });

  it("puts no date on a charge that recurs on no schedule, and says it will still cost money", () => {
    const c = buildCalendar([charge({ cadence: "irregular" })], undefined, { from: "2026-07-01", to: "2026-12-31" });
    expect(c.obligations).toEqual([]);
    expect(c.notes.join(" ")).toContain("no predictable schedule");
  });

  it("leaves a cancelled-looking charge off, and says the months are light by that much if it renews", () => {
    const c = buildCalendar([charge({ lapsed: true })], undefined, { from: "2026-07-01", to: "2026-12-31" });
    expect(c.obligations).toEqual([]);
    expect(c.notes.join(" ")).toContain("EXAMPLE SUBSCRIPTION");
    expect(c.notes.join(" ")).toContain("light by that much");

    const forced = buildCalendar([charge({ lapsed: true })], undefined, {
      from: "2026-07-01",
      to: "2026-12-31",
      includeLapsed: true,
    });
    expect(forced.obligations).toHaveLength(6);
  });

  it("marks a ragged rhythm as assumed rather than observed", () => {
    const c = buildCalendar([charge({ regularity: 0.5 })], undefined, { from: "2026-07-01", to: "2026-08-31" });
    expect(c.obligations.every((o) => o.confidence === "assumed")).toBe(true);
    const tight = buildCalendar([charge({ regularity: 0.95 })], undefined, { from: "2026-07-01", to: "2026-08-31" });
    expect(tight.obligations.every((o) => o.confidence === "observed")).toBe(true);
  });
});

describe("buildCalendar — minimum payments", () => {
  const card = {
    account: "card",
    institution: "Example Card Co",
    kind: "credit" as const,
    balance: usd(-2000),
    asOf: "2026-06-30",
    rolledForward: 0,
    isDebt: true,
    owed: usd(2000),
    minimumPayment: usd(75),
  };

  it("places an unknown due day on the 1st — the earliest it could fall, so the calendar cannot be optimistic", () => {
    const c = buildCalendar([], positionWith([card]), { from: "2026-07-01", to: "2026-09-30" });
    expect(minimumsOn(c).map((o) => o.date)).toEqual(["2026-07-01", "2026-08-01", "2026-09-01"]);
    expect(minimumsOn(c).every((o) => o.confidence === "assumed")).toBe(true);
    expect(c.notes.join(" ")).toContain("earliest it could plausibly fall");
  });

  it("uses the real due day when it is known, and calls it observed", () => {
    const c = buildCalendar([], positionWith([card]), {
      from: "2026-07-01",
      to: "2026-09-30",
      minimumDueDay: { card: 22 },
    });
    expect(minimumsOn(c).map((o) => o.date)).toEqual(["2026-07-22", "2026-08-22", "2026-09-22"]);
    expect(minimumsOn(c).every((o) => o.confidence === "observed")).toBe(true);
    expect(c.notes).toEqual([]);
  });

  it("clamps a due day past the end of a short month", () => {
    const c = buildCalendar([], positionWith([card]), {
      from: "2026-01-01",
      to: "2026-03-31",
      minimumDueDay: { card: 31 },
    });
    expect(minimumsOn(c).map((o) => o.date)).toEqual(["2026-01-31", "2026-02-28", "2026-03-31"]);
  });

  it("asks nothing of a debt that is paid off", () => {
    const clear = { ...card, owed: undefined, balance: usd(0) };
    const c = buildCalendar([], positionWith([clear]), { from: "2026-07-01", to: "2026-09-30" });
    expect(minimumsOn(c)).toEqual([]);
  });
});

describe("buildCalendar — reading the calendar", () => {
  const rent: Recurring = charge({ key: "rent", label: "RENT", account: "checking", typical: usd(1500), lastSeen: "2026-06-01" });
  const sub = charge({ lastSeen: "2026-06-15" });
  const insurance = charge({ key: "insurance", label: "INSURANCE", typical: usd(900), cadence: "annual", lastSeen: "2025-09-03" });

  const cal = () => buildCalendar([rent, sub, insurance], undefined, { from: "2026-07-01", to: "2026-12-31" });

  it("totals each month and names the heaviest", () => {
    const c = cal();
    expect(c.byMonth.map((m) => m.month)).toEqual(["2026-07", "2026-08", "2026-09", "2026-10", "2026-11", "2026-12"]);
    // September carries the annual insurance renewal on top of the usual two.
    expect(c.heaviest!.month).toBe("2026-09");
    expect(c.heaviest!.total.minor).toBe(usd(1500 + 14.99 + 900).minor);
    expect(monthTotal(c, "2026-07", "USD").minor).toBe(usd(1514.99).minor);
    expect(monthTotal(c, "2027-01", "USD").minor).toBe(0);
  });

  it("is sorted by date", () => {
    const dates = cal().obligations.map((o) => o.date);
    expect([...dates].sort()).toEqual(dates);
  });

  it("answers 'can I get to Friday' with a window, not a month", () => {
    const c = cal();
    expect(dueBetween(c, "2026-07-01", "2026-07-10").map((o) => o.label)).toEqual(["RENT"]);
    expect(dueBetween(c, "2026-07-16", "2026-07-31")).toEqual([]);
  });

  it("finds the heaviest run of days, where a month-level view goes blind", () => {
    const w = heaviestWindow(cal(), 7)!;
    // 1 September rent and 3 September insurance fall inside one week; no month total says that.
    expect(w.from).toBe("2026-09-01");
    expect(w.total.minor).toBe(usd(2400).minor);
  });

  it("has nothing to say about an empty calendar rather than inventing a zero month", () => {
    const c = buildCalendar([], undefined, { from: "2026-07-01", to: "2026-12-31" });
    expect(c.obligations).toEqual([]);
    expect(c.byMonth).toEqual([]);
    expect(c.heaviest).toBeUndefined();
    expect(heaviestWindow(c, 7)).toBeUndefined();
  });
});
